from typing import List, Tuple

def process_queries(Q: int, queries: List[Tuple[int, int]]) -> List[int]:
    A = []
    results = []
    for query in queries:
        t, x_or_k = query
        if t == 1:
            A.append(x_or_k)
        elif t == 2:
            results.append(A[-x_or_k])
    return results
